//! Protobuf messages exchanged with the tag monitor.
//!
//! Generated by `build.rs` from `proto/tag.proto` and `proto/tagdata.proto`,
//! the same definitions the C++ host tools and the firmware's nanopb code
//! use. A request is a [`Req`] whose `payload` selects the operation; every
//! reply is an [`Ack`] with an [`ack::Err`] code and an optional payload.

#![allow(clippy::all, missing_docs)]

include!(concat!(env!("OUT_DIR"), "/_.rs"));

impl Ack {
    /// The firmware's error text, or `""` when the payload is not
    /// `error_message`. Matches the C++ `Ack::error_message()` accessor,
    /// which returns an empty string for an unset oneof member.
    pub fn error_message(&self) -> &str {
        match &self.payload {
            Some(ack::Payload::ErrorMessage(message)) => message,
            _ => "",
        }
    }
}
